def feedback(guess, secret):
    out = ''
    for i in range(5):
        if guess[i] == secret[i]:
            out += 'G'
        elif guess[i] in secret:
            out += 'Y'
        else:
            out += 'B'
    return out

def gen(rng):
    tests = [
        '12345 GGGYY', '12345 GGYYY', '12345 GGGGG', '11111 GBGGG', '12345 YYYYY', '12345 BBBBB',
        '11111 BBBBB', '90909 GBGBG', '12345 GGGGY', '55555 YYYYY', '10000 GBBBB', '98765 BYYYB',
    ]
    for _ in range(50):
        if rng.random() < 0.7:
            guess = str(rng.randint(10000, 99999))
            if rng.random() < 0.4:
                guess = str(rng.randint(1, 9)) + ''.join(rng.choice('0123') for _ in range(4))
            secret = str(rng.randint(10000, 99999))
            if rng.random() < 0.5:
                secret = ''.join(rng.choice(guess) for _ in range(5))
                if secret[0] == '0':
                    secret = '1' + secret[1:]
            tests.append(guess + ' ' + feedback(guess, secret))
        else:
            guess = str(rng.randint(10000, 99999))
            tests.append(guess + ' ' + ''.join(rng.choice('GYB') for _ in range(5)))
    return tests
